#!/usr/bin/env python3
"""Fixed PostgreSQL18.6 ordinary VALUES/set-root FETCH grammar and values.

900 exact Simple/ParseDescribe/valid-unlimited-Extended controls over four
real query-root forms. The original artifact also retains ten standalone
SELECT observations; that separate, unimplemented lowering is not accepted
by this fixture. No retained-planning, portal-format or input-frame repair.
"""
import argparse
from contextlib import contextmanager
import importlib.util
import json
import os
