runner=importlib.util.module_from_spec(spec);spec.loader.exec_module(runner)
wire=runner.load_protocol_client()
LABEL="QUERY_ROOT_FETCH_PROTOCOL"
EXPECTED_CONTROLS=900

def cases():
    bases={
        "values":"VALUES(3),(1),(1),(2) ORDER BY column1",
        "bare_set_values":"VALUES(3),(1) UNION ALL VALUES(1),(2) ORDER BY 1",
        "parenthesized_set_values":"((VALUES(3),(1)) UNION ALL VALUES(1),(2)) ORDER BY 1",
        "set_select":"SELECT 3 AS n UNION ALL SELECT 1 UNION ALL SELECT 1 UNION ALL SELECT 2 ORDER BY 1",
    }
    counts=["", "0", "1", "+1", "-0", "-1", "1.5", "+1.5", "-1.5",
        "NULL", "(NULL)", "((NULL))", "(NULL::bigint)", "CAST(NULL AS bigint)",
        "CASE WHEN true THEN NULL ELSE 1 END", "(SELECT NULL::bigint)", "(VALUES(NULL::bigint))",
        "(1+1)", "1+1", "NULL::bigint", "int8 '2'", "'2'", "'bad'", "TRUE", "abs(-1)",
        "row(1)", "(1,2)", "column1", "missing_name", "(1+)", "CASE WHEN true THEN 1"]
    tails=["OFFSET 1+1", "OFFSET 1+1 ROWS", "OFFSET (1+1) ROWS", "OFFSET 1::bigint ROWS",
        "OFFSET (1::bigint) ROW", "OFFSET abs(1) ROWS", "FETCH NEXT ROW ONLY",
        "FETCH FIRST (2) ROW ONLY", "FETCH FIRST (2) ONLY", "FETCH FIRST ROWS ONLY",
        "FETCH FIRST 1 ROW ONLY OFFSET (1+0) ROWS", "OFFSET (1+0) ROWS FETCH FIRST (1+1) ROWS ONLY",
        "FETCH FIRST (1) ROWS WITH TIES FETCH NEXT ROW ONLY", "FETCH FIRST ALL ROWS ONLY",
        "FETCH FIRST DEFAULT ROWS ONLY", "FETCH FIRST 1 ROWS WITH TIES LIMIT 2"]
    result=[]
    for root,base in bases.items():
        for count in counts:
            for ending in ("ONLY","WITH TIES"):
                tail="FETCH FIRST "+(count+" " if count else "")+"ROWS "+ending
                result.append(dict(root=root,form=count,tail=tail,sql=base+" "+tail,oids=[],inputs=[]))
        for tail in tails:
            result.append(dict(root=root,form="tail",tail=tail,sql=base+" "+tail,oids=[],inputs=[]))
        for value,inputs,ending in [
                ("$1",[None],"ONLY"),("$1",[None],"WITH TIES"),("($1)",[None],"WITH TIES"),
                ("$1",["1"],"ONLY"),("$1",["-1"],"ONLY"),("($1+1)",["0"],"WITH TIES"),
                ("($1+1)",[None],"WITH TIES"),("$1+1",["0"],"ONLY"),("-$1",["1"],"ONLY"),
                ("(-$1)",["1"],"ONLY"),("$1::bigint",["1"],"ONLY"),
                ("($1::bigint)",[None],"WITH TIES")]:
            tail="FETCH FIRST "+value+" ROWS "+ending
            result.append(dict(root=root,form=value,tail=tail,sql=base+" "+tail,oids=[20],inputs=inputs))
    # Separate standalone SELECT controls establish PG syntax, without
    # declaring this batch's unsupported standalone lowering implemented.
    for tail in ("FETCH FIRST (1+1) ROWS ONLY", "FETCH FIRST NULL ROWS WITH TIES",
                 "FETCH FIRST (NULL) ROWS WITH TIES", "FETCH FIRST (NULL::bigint) ROWS WITH TIES"):
        result.append(dict(root="standalone_select_control",form="control",tail=tail,
            sql="SELECT 1 AS n ORDER BY n "+tail,oids=[],inputs=[]))
    assert len(result)==364
    return result


def observe(messages):
    rows,state,message,headers,tag,oids=runner.decode_wire_result(messages,include_types=True)
    return dict(rows=rows,state=state,message=message,headers=headers,tag=tag,oids=oids,
        frames=[kind.decode() for kind,_ in messages],ready=[body.decode() for kind,body in messages if kind==b"Z"],
        parameter_oids=[[struct.unpack("!I",body[index:index+4])[0] for index in range(2,len(body),4)]
                        for kind,body in messages if kind==b"t"],
        diagnostics=[{key.decode():value.decode() for key,value in wire.diagnostic_fields(body).items()}
                     for kind,body in messages if kind==b"E"],
        raw=[dict(kind=kind.decode(),body_hex=body.hex()) for kind,body in messages])


