@contextmanager
def connection(reference):
    if reference:
        host,port,user,database,password=runner._reference_connection_settings()
        sock=socket.create_connection((host,port),timeout=runner.wire_timeout())
        try:
            wire.startup_reference(sock,user,database,password=password)
            runner.verify_reference_version(wire,sock)
            yield SimpleNamespace(sock=sock)
        finally:sock.close()
    else:
        server=runner.start_ours(wire)
        try:yield SimpleNamespace(sock=server["sock"])
        finally:runner.stop_ours(server)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--reference18",action="store_true")
    args=parser.parse_args()
    supplied=os.environ.get("QUERY_ROOT_FETCH_OUTPUT_DIR")
    output=Path(supplied) if supplied else Path(tempfile.mkdtemp(prefix="dbms-query-root-fetch-"))
    output.mkdir(parents=True,exist_ok=True)
    matrix=cases()[:360]
    assert len(matrix)==360 and all(case["root"]!="standalone_select_control" for case in matrix)
    assert len(ORACLE)==EXPECTED_CONTROLS
    expected={(entry["case"],entry["phase"]):entry for entry in ORACLE}
    observations=[];failures=0;complete=False
    def record(index,phase,messages):
        nonlocal failures
        actual=observe(messages);entry=expected[(index,phase)]
        assert entry["sql"]==matrix[index]["sql"]
        valid=all(actual[key]==value for key,value in entry["expected"].items())
        observation=dict(case=index,phase=phase,sql=entry["sql"],expected=entry["expected"],actual=actual,passed=valid)
        observations.append(observation);failures+=not valid
        print(LABEL,json.dumps(observation),flush=True)
        return actual
    try:
        with connection(args.reference18) as client:
            client.sock.settimeout(15)
            for index,case in enumerate(matrix):
                sql=case["sql"]
                if not case["oids"]:record(index,"Simple",wire.simple_query(client.sock,sql))
                name=("fetch_meta_"+str(index)).encode()
                payload=name+b"\0"+sql.encode()+b"\0"+struct.pack("!H",len(case["oids"]))+b"".join(struct.pack("!I",oid) for oid in case["oids"])
                client.sock.sendall(wire.typed(b"P",payload)+wire.typed(b"D",b"S"+name+b"\0")+wire.typed(b"S"))
                record(index,"ParseDescribe",wire.read_until_ready(client.sock))
                if (index,"ParseBindExecute") in expected:
                    execute_name=("fetch_exec_"+str(index)).encode()
                    parse=execute_name+b"\0"+sql.encode()+b"\0"+struct.pack("!H",len(case["oids"]))+b"".join(struct.pack("!I",oid) for oid in case["oids"])
                    bind=b"\0"+execute_name+b"\0"+struct.pack("!HH",0,len(case["inputs"]))
                    for value in case["inputs"]:
                        if value is None:bind+=struct.pack("!i",-1)
                        else:
                            encoded=value.encode();bind+=struct.pack("!i",len(encoded))+encoded
                    bind+=struct.pack("!H",0)
                    client.sock.sendall(wire.typed(b"P",parse)+wire.typed(b"B",bind)+wire.typed(b"D",b"P\0")+
                        wire.typed(b"E",b"\0"+struct.pack("!I",0))+wire.typed(b"S"))
                    record(index,"ParseBindExecute",wire.read_until_ready(client.sock))
        complete=True
    finally:
        path=output/("reference-observations.json" if args.reference18 else "observations.json")
        path.write_text(json.dumps(dict(complete=complete,controls=observations,failures=failures),indent=2)+"\n")
        print(LABEL+"_OBSERVATIONS",str(path),flush=True)
    print(LABEL+"_COMPLETE",len(observations),"FAILURES",failures,flush=True)
    assert complete and len(observations)==EXPECTED_CONTROLS and not failures


if __name__=="__main__":main()
